{
  "summary": "On 2026-09-16 card payments failed at about a quarter of arrivals because card-processor-proxy-02 was evicted, leaving only proxy-01 which ran out of its token budget and generated CPX-W430 errors.",
  "likely_cause": "Eviction of card-processor-proxy-02 left a single proxy instance whose token budget (180 RPS) was insufficient for the arrival rate (~240 RPS), causing rate‑limit rejections.",
  "confidence": "high",
  "claims": [
    {
      "text": "card-processor-proxy-02 was evicted, leaving only proxy-01 running.",
      "evidence_ids": ["INC-0197#1"],
      "quote": "pod listing for the proxy shows -01 Running and the replacement Pending"
    },
    {
      "text": "Payments arrived at roughly 240 per second.",
      "evidence_ids": ["INC-0197#1"],
      "quote": "Payments come in at roughly 240 per second."
    },
    {
      "text": "Each proxy instance has a token budget of 180 RPS; attempts that cannot get a token are dropped with CPX-W430.",
      "evidence_ids": ["INC-0177#1"],
      "quote": "one instance is 180 a second. An attempt that cannot get a token ... is dropped here and logs `CPX-W430`"
    },
    {
      "text": "All rejections came from card-processor-proxy-01.",
      "evidence_ids": ["INC-0197#1"],
      "quote": "every rejection comes from card-processor-proxy-01"
    }
  ],
  "next_checks": [
    "Verify token‑budget configuration for card-processor-proxy instances.",
    "Check the health and scheduling of card-processor-proxy-02 and its node.",
    "Monitor egress node taints and cordon status during maintenance."
  ]
}
